import { useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { calculateCost } from '../config/ai_cost';

interface ATBalanceCheckProps {
    service: string;
    params?: Record<string, number>;
    onReady?: () => void;
    children?: React.ReactNode;
}

export default function ATBalanceCheck({
    service,
    params,
    onReady,
    children
}: ATBalanceCheckProps) {
    const { user } = useAuth();
    // Use memoization instead of effect for cost
    const estimatedCost = useMemo(() => {
        try {
            return calculateCost(service, params);
        } catch {
            return 0;
        }
    }, [service, params]);
    const [isChecking, setIsChecking] = useState<boolean>(true);
    const [balanceOk, setBalanceOk] = useState<boolean>(false);

    const checkBalance = useCallback(() => {
        // 计算预估AT币消耗
        let cost = 0;
        try {
            cost = calculateCost(service, params);
        } catch { /* ignore */ }

        if (user) {
            const ok = (user.atBalance || 0) >= cost;
            setBalanceOk(ok);

            if (!ok) {
                // AT币不足，显示警告
                window.dispatchEvent(new CustomEvent('at-balance-insufficient', {
                    detail: {
                        message: `${service}服务需要${cost} AT币`,
                        estimatedCost: cost,
                        currentBalance: user.atBalance
                    }
                }));
            }
        }

        setIsChecking(false);
    }, [service, params, user, setBalanceOk, setIsChecking]);

    useEffect(() => {
        checkBalance();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [service, params, user?.atBalance, checkBalance]); // Added checkBalance to useEffect dependencies

    if (isChecking) {
        return <div>检查AT币余额...</div>;
    }

    if (!balanceOk) {
        return (
            <div className="at-balance-warning">
                <div className="warning-header">
                    <span className="warning-icon">⚠️</span>
                    <span className="warning-title">AT币余额不足</span>
                </div>
                <div className="warning-content">
                    <p>本次{service}练习需要消耗约 <strong>{estimatedCost} AT币</strong>。</p>
                    <p>您的当前余额为 <strong>{user?.atBalance || 0} AT币</strong>。</p>
                    <div className="warning-actions">
                        <button
                            className="primary-button"
                            onClick={() => window.location.href = '/profile'}
                        >
                            前往充值
                        </button>
                        <button
                            className="secondary-button"
                            onClick={onReady}
                        >
                            尝试使用
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    // 余额充足，显示children
    return children || null;
}

import { useEffect, useState, useCallback } from 'react';
import '../styles/toast.css';

export type ToastType = 'error' | 'success';

interface ToastItem {
    id: number;
    message: string;
    type: ToastType;
    code?: string | number;
}

let toastId = 0;
let addToastFn: ((message: string, type: ToastType, code?: string | number) => void) | null = null;

/**
 * 全局调用方法，替代 alert()
 * 用法：
 *   showToast('操作成功！', 'success');                // 绿色卡片
 *   showToast('请求异常', 'error', 400);              // 红色卡片，显示 "400：请求异常"
 *   showToast('网络异常，请重试', 'error');             // 红色卡片，显示 "异常：网络异常，请重试"
 */
export function showToast(message: string, type: ToastType = 'error', code?: string | number) {
    if (addToastFn) {
        addToastFn(message, type, code);
    } else {
        console.warn('[Toast fallback]', message);
    }
}

/**
 * Toast 容器组件 —— 放在 App 根组件中即可
 * <ToastContainer />
 */
export default function ToastContainer() {
    const [toasts, setToasts] = useState<ToastItem[]>([]);

    const addToast = useCallback((message: string, type: ToastType, code?: string | number) => {
        const id = ++toastId;
        setToasts(prev => [...prev, { id, message, type, code }]);

        // 3 秒后自动消失
        setTimeout(() => {
            setToasts(prev => prev.filter(t => t.id !== id));
        }, 3000);
    }, []);

    // 注册全局函数
    useEffect(() => {
        addToastFn = addToast;
        return () => { addToastFn = null; };
    }, [addToast]);

    const removeToast = (id: number) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    };

    return (
        <div className="toast-container">
            {toasts.map(t => (
                <div
                    key={t.id}
                    className={`toast-card toast-${t.type}`}
                    onClick={() => removeToast(t.id)}
                >
                    <span className="toast-icon">
                        {t.type === 'error' ? '✕' : '✓'}
                    </span>
                    <span className="toast-message">
                        {t.type === 'error'
                            ? <><span className="toast-code">{t.code ?? '异常'}</span>：{t.message}</>
                            : t.message
                        }
                    </span>
                </div>
            ))}
        </div>
    );
}

import React, { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
import { type User, authApi } from '../api/auth';

interface AuthContextType {
    user: User | null;
    isLoading: boolean;
    login: (tokens: { access: string, refresh: string }, userData: User) => void;
    logout: () => void;
    updateUser: (userData: User) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const initAuth = async () => {
            const token = localStorage.getItem('access_token');
            if (token) {
                try {
                    const userData = await authApi.getProfile();
                    setUser(userData);
                } catch (error) {
                    console.error('Failed to restore session:', error);
                    // Automatic token refresh logic in client.ts will handle 401s.
                    // If it completely fails, localStorage is cleared and auth:logout is dispatched.
                }
            }
            setIsLoading(false);
        };

        initAuth();

        const handleLogout = () => {
            setUser(null);
            localStorage.removeItem('access_token');
            localStorage.removeItem('refresh_token');
        };

        const handleATConsumed = (event: Event) => {
            const customEvent = event as CustomEvent<{ consumed: number; description?: string }>;
            // 更新用户AT币余额
            const detail = customEvent.detail;
            if (user && detail.consumed) {
                const updatedUser = {
                    ...user,
                    atBalance: (user.atBalance || 0) - detail.consumed
                };
                setUser(updatedUser);
                console.log(`AT币消耗更新: ${detail.consumed} AT, 新余额: ${updatedUser.atBalance} AT`);
            }
        };

        window.addEventListener('auth:logout', handleLogout);
        window.addEventListener('at-consumed', handleATConsumed);
        return () => {
            window.removeEventListener('auth:logout', handleLogout);
            window.removeEventListener('at-consumed', handleATConsumed);
        };
    }, []);

    const login = (tokens: { access: string; refresh: string }, userData: User) => {
        localStorage.setItem('access_token', tokens.access);
        localStorage.setItem('refresh_token', tokens.refresh);
        setUser(userData);
    };

    const logout = () => {
        setUser(null);
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
    };

    const updateUser = (userData: User) => {
        setUser(userData);
    };

    return (
        <AuthContext.Provider value={{ user, isLoading, login, logout, updateUser }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
import type { Lang } from './translations';

interface LanguageContextValue {
    lang: Lang;
    setLang: (lang: Lang) => void;
}

const LanguageContext = createContext<LanguageContextValue>({
    lang: 'zh',
    setLang: () => { },
});

export function LanguageProvider({ children }: { children: ReactNode }) {
    const [lang, setLangState] = useState<Lang>(() => {
        const saved = localStorage.getItem('ielts_lang');
        return (saved === 'zh' || saved === 'en') ? saved : 'zh';
    });

    const setLang = (newLang: Lang) => {
        setLangState(newLang);
        localStorage.setItem('ielts_lang', newLang);
    };

    // Sync html lang attribute for accessibility
    useEffect(() => {
        document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
    }, [lang]);

    return (
        <LanguageContext.Provider value={{ lang, setLang }}>
            {children}
        </LanguageContext.Provider>
    );
}

export function useLang() {
    return useContext(LanguageContext);
}

// ListeningPractice.tsx
import { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { createListeningState } from '../store/listen_page_store';
import type { VocabItem, ListeningData } from '../store/listen_page_store';
import { api } from '../api/client';
import { showToast } from '../components/Toast';
import '../styles/listening_page.css';
import '../styles/reading_page.css';

// 数字英文映射（用于答案比对）
const numberWords: Record<string, string> = {
    '0': 'zero', '1': 'one', '2': 'two', '3': 'three', '4': 'four',
    '5': 'five', '6': 'six', '7': 'seven', '8': 'eight', '9': 'nine',
    '10': 'ten', '11': 'eleven', '12': 'twelve', '13': 'thirteen',
    '14': 'fourteen', '15': 'fifteen', '16': 'sixteen', '17': 'seventeen',
    '18': 'eighteen', '19': 'nineteen', '20': 'twenty',
    '30': 'thirty', '40': 'forty', '50': 'fifty', '60': 'sixty',
    '70': 'seventy', '80': 'eighty', '90': 'ninety', '100': 'hundred',
    '1000': 'thousand',
};

function normalizeAnswer(ans: string): string {
    let s = ans.trim().toLowerCase().replace(/\s+/g, ' ');
    Object.entries(numberWords).forEach(([num, word]) => {
        s = s.replace(new RegExp(`\\b${num}\\b`, 'g'), word);
    });
    return s;
}

function checkAnswer(userAns: string, acceptableAnswers: string[]): boolean {
    const norm = normalizeAnswer(userAns);
    return acceptableAnswers.some(a => normalizeAnswer(a) === norm);
}

export default function ListeningPage() {
    const { state } = useLocation();
    const vocabInput: string = state?.vocabInput ?? '';
    const difficulty: string = state?.difficulty ?? '7.0';
    const wordCountMin: number = state?.wordCountMin ?? 1;
    const wordCountMax: number = state?.wordCountMax ?? 2;
    const practiceType: 'article' | 'sentence' = state?.practiceType ?? 'article';
    const navigate = useNavigate();
    const onReturnHome = () => navigate('/');

    const [st, setSt] = useState(createListeningState);
    const set = <K extends keyof typeof st>(k: K, v: typeof st[K]) =>
        setSt(s => ({ ...s, [k]: v }));

    const [renderTick, setRenderTick] = useState(0);

    const userAnswersRef = useRef<Record<number, string>>({});
    const hasRequested = useRef(false);
    const audioRef = useRef<HTMLAudioElement | null>(null);
    const [audioUrl, setAudioUrl] = useState<string | null>(null);

    const [ttsStarted, setTtsStarted] = useState(false);
    const [ttsSpeaking, setTtsSpeaking] = useState(false);
    const [audioLoading, setAudioLoading] = useState(false);

    // 清理 URL 对象
    useEffect(() => {
        return () => {
            if (audioUrl) {
                URL.revokeObjectURL(audioUrl);
            }
        };
    }, [audioUrl]);

    useEffect(() => {
        if (hasRequested.current) return;
        hasRequested.current = true;
        setSt(createListeningState());
        generateListening();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const formatHighlight = (text: string): string => {
        if (!text) return '';
        return text.replace(/\*\*(.*?)\*\*/g, '<span class="highlight">$1</span>');
    };

    // 去掉 ** 标记用于 TTS
    const stripMarkers = (text: string): string => {
        return text.replace(/\*\*/g, '');
    };

    const generateListening = async () => {
        const parsedList: VocabItem[] = vocabInput.trim().split('\n').map(line => {
            const parts = line.split(/[-:]/);
            return {
                word: parts[0] ? parts[0].trim() : '',
                meaning: parts[1] ? parts[1].trim() : ''
            };
        }).filter(item => item.word).sort((a, b) => a.word.localeCompare(b.word));

        set('vocabList', parsedList);
        const words = parsedList.map(v => v.word);

        try {
            const parsedData = await api<ListeningData>('/listening/generate', {
                method: 'POST',
                body: { words, difficulty, wordCountMin, wordCountMax, practiceType },
            });

            // 获取文本之后立马生成音频
            const passageText = stripMarkers(parsedData.passage);
            const introText = 'The IELTS listening test is about to begin. Please listen carefully.';
            const fullText = `${introText}\n\n\n\n${passageText}`;

            // Show audio loading indicator
            setAudioLoading(true);
            set('isLoading', false); // Show content but with audio spinner

            const res = await fetch(`${import.meta.env.VITE_API_BASE}/api/listening/audio`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ text: fullText })

            });

            if (!res.ok) {
                console.warn(`Failed to generate audio: ${res.statusText}`);
                // 即使音频生成失败，也把题目展示出来，但不打断流程
            } else {
                const blob = await res.blob();
                const url = URL.createObjectURL(blob);
                setAudioUrl(url);

                const audio = new Audio(url);
                audioRef.current = audio;

                audio.onended = () => {
                    setTtsSpeaking(false);
                    setTtsStarted(false); // 允许重播
                };

                audio.onerror = () => {
                    console.error("Audio playback error");
                    setTtsSpeaking(false);
                    setTtsStarted(false);
                };
            }
            setAudioLoading(false);

            set('listeningData', parsedData);
            // 前端防御：确保 questions 存在
            if (!parsedData.questions || parsedData.questions.length === 0) {
                showToast('AI 未能生成题目，请重试', 'error');
                onReturnHome();
                return;
            }
            userAnswersRef.current = {};
            if (practiceType === 'article') {
                set('isRightOpen', true);
            }
        } catch (err: unknown) {
            console.error("API Error:", err);
            const error = err as { message?: string, status?: number };
            showToast(error.message || '请求失败', 'error', error.status);
            onReturnHome();
        } finally {
            set('isLoading', false);
        }
    };

    const submitQuiz = () => {
        if (!st.listeningData) return;
        const totalQuestions = st.listeningData.questions.length;
        const answeredQuestions = Object.keys(userAnswersRef.current).length;
        if (answeredQuestions < totalQuestions) {
            if (!window.confirm('You have unanswered questions. Submit anyway?')) return;
        }
        // 停止 TTS
        if (audioRef.current) {
            audioRef.current.pause();
        }
        setTtsSpeaking(false);
        set('step', 3);
    };

    // 播放已经预提取的音频
    const startTTS = async () => {
        if (!audioRef.current || ttsStarted) return;
        setTtsStarted(true);
        setTtsSpeaking(true);

        try {
            // 从头开始播放
            audioRef.current.currentTime = 0;
            await audioRef.current.play();
        } catch (err: unknown) {
            console.error("Audio playback error:", err);
            setTtsSpeaking(false);
            setTtsStarted(false);
            showToast('播放音频时出错，系统可能限制了自动播放', 'error');
        }
    };

    // Resizer logic (REMOVED: The layout is now single-column with inline inputs)

    // Resizer for results page passage sidebar
    useEffect(() => {
        const sidebar = document.getElementById('listeningPassageSidebar');
        if (!st.isPassageOpen) {
            if (sidebar) sidebar.style.width = '';
            return;
        }
        if (st.step !== 3) return;
        const resizer = document.getElementById('listeningResizerPassage');
        const layout = document.getElementById('listeningResultsLayout');
        if (!resizer || !sidebar || !layout) return;

        let isResizing = false, startX = 0, startWidth = 0;

        const onMouseDown = (e: MouseEvent) => {
            isResizing = true;
            startX = e.clientX;
            startWidth = sidebar.getBoundingClientRect().width;
            layout.classList.add('is-resizing');
            resizer.classList.add('resizing');
        };
        const onMouseMove = (e: MouseEvent) => {
            if (!isResizing) return;
            const newWidth = startWidth + (e.clientX - startX);
            if (newWidth > 200 && newWidth < window.innerWidth * 0.55) {
                sidebar.style.width = newWidth + 'px';
            }
        };
        const onMouseUp = () => {
            if (isResizing) {
                isResizing = false;
                layout.classList.remove('is-resizing');
                resizer.classList.remove('resizing');
            }
        };

        resizer.addEventListener('mousedown', onMouseDown);
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
        return () => {
            resizer.removeEventListener('mousedown', onMouseDown);
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [st.step, st.isPassageOpen]);

    // Loading — two distinct phases
    if (st.isLoading) {
        return (
            <div className="container">
                <div className="page" style={{ justifyContent: 'center', alignItems: 'center' }}>
                    <div className="loader">
                        🧠 AI is writing your IELTS {difficulty} level listening passage... Please wait.
                    </div>
                </div>
            </div>
        );
    }

    if (audioLoading) {
        return (
            <div className="container">
                <div className="page" style={{ justifyContent: 'center', alignItems: 'center' }}>
                    <div className="loader">
                        🔊 Generating audio... Please wait.
                    </div>
                </div>
            </div>
        );
    }

    // Practice Page
    if (st.step === 2 && st.listeningData) {
        const isArticleMode = st.listeningData.type === 'article';
        const isMultipleChoiceMode = st.listeningData.type === 'multiple_choice';

        // 去除原文所有的 ** 标记（考试呈现时不需要加粗高亮）
        const removeMarkdown = (text: string) => {
            if (!text) return '';
            return text.replace(/\*\*/g, '');
        };

        // 辅助渲染内联填空
        const renderInlineInput = (qId: number, idx: number) => {
            return (
                <input
                    key={`input-${qId}-${idx}`}
                    type="text"
                    className="inline-answer-input"
                    placeholder={qId.toString()}
                    defaultValue={userAnswersRef.current[qId] || ''}
                    onChange={(e) => { userAnswersRef.current[qId] = e.target.value; }}
                />
            );
        };

        const renderSentenceMode = () => {
            if (st.listeningData?.type !== 'sentence') return null;
            return st.listeningData.questions.slice(0, 10).map(q => {
                const parts = q.question.split('_____');
                return (
                    <div key={q.id} className="inline-q-block">
                        <span className="q-number">{q.id}.</span>
                        {parts.map((p: string, i: number) => (
                            <span key={i}>
                                <span>{removeMarkdown(p)}</span>
                                {i < parts.length - 1 && renderInlineInput(q.id, i)}
                            </span>
                        ))}
                    </div>
                );
            });
        };

        const renderArticleMode = () => {
            if (st.listeningData?.type !== 'article') return null;
            const textToSplit = st.listeningData.blanked_passage || st.listeningData.passage;
            const paragraphs = textToSplit.split('\n\n');
            let blankCounter = 1;

            return (
                <div className="listening-article-inline">
                    <h2 style={{ marginTop: 0 }}>{removeMarkdown(st.listeningData.title)}</h2>
                    {paragraphs.map((p: string, pIdx: number) => {
                        const parts = p.split('_____');
                        return (
                            <p key={pIdx} style={{ lineHeight: 2.2 }}>
                                {parts.map((partText: string, i: number) => (
                                    <span key={i}>
                                        <span>{removeMarkdown(partText)}</span>
                                        {i < parts.length - 1 && renderInlineInput(blankCounter++, i)}
                                    </span>
                                ))}
                            </p>
                        );
                    })}
                </div>
            );
        };

        const renderMultipleChoiceMode = () => {
            if (st.listeningData?.type !== 'multiple_choice') return null;
            return (
                <div className="listening-mc-mode" key={`tick-${renderTick}`}>
                    {st.listeningData.questions.map((q: any) => (
                        <div key={q.id} className="mc-q-block" style={{ marginBottom: '24px' }}>
                            <div className="q-number" style={{ fontWeight: 'bold', marginBottom: '8px' }}>
                                {q.id}. {removeMarkdown(q.question)}
                            </div>
                            <div className="mc-options" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                                {Object.entries(q.options || {}).map(([key, optText]) => (
                                    <label key={key} className="mc-option-label" style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                                        <input
                                            type="radio"
                                            name={`q-${q.id}`}
                                            value={key}
                                            checked={userAnswersRef.current[q.id] === key}
                                            onChange={(e) => {
                                                userAnswersRef.current[q.id] = e.target.value;
                                                // 触发重渲染以更新选中状态
                                                setRenderTick(t => t + 1);
                                            }}
                                        />
                                        <span style={{ fontWeight: 600 }}>{key}.</span> <span>{optText as string}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            );
        };

        return (
            <div className="container">
                <div className="page listening-page">
                    <div className="toolbar-area">
                        <div>
                            {!ttsStarted ? (
                                <button className="tts-start-btn" onClick={startTTS}>
                                    🔊 开始播放
                                </button>
                            ) : (
                                <span className={`tts-status ${ttsSpeaking ? 'speaking' : 'done'}`}>
                                    {ttsSpeaking ? '🔊 正在朗读...' : '✅ 朗读结束'}
                                </span>
                            )}
                        </div>
                        <div className="toolbar-info-badges">
                            <span className="toolbar-badge mode-badge">
                                {isArticleMode ? '📄 文章填空' : isMultipleChoiceMode ? '🎯 选择题' : '✏️ 句子填空'}
                            </span>
                            {!isMultipleChoiceMode && (
                                <span className="toolbar-badge limit-badge">
                                    ✍️ 每空不超过 {wordCountMax === wordCountMin
                                        ? `${wordCountMax} 个词`
                                        : `${wordCountMin}–${wordCountMax} 个词`}
                                </span>
                            )}
                        </div>
                    </div>

                    <div className="listening-content-area">
                        {isArticleMode ? renderArticleMode() : isMultipleChoiceMode ? renderMultipleChoiceMode() : renderSentenceMode()}

                        <div className="submit-quiz-container" style={{ marginTop: '40px', paddingBottom: '40px' }}>
                            <button onClick={submitQuiz}>Submit Answers</button>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // Results Page
    if (st.step === 3 && st.listeningData) {
        let score = 0;
        const isMultipleChoiceMode = st.listeningData.type === 'multiple_choice';

        st.listeningData.questions.forEach((q: any) => {
            const userAns = userAnswersRef.current[q.id] || '';
            if (isMultipleChoiceMode) {
                if (userAns.trim().toUpperCase() === q.answer?.trim().toUpperCase()) score++;
            } else {
                if (checkAnswer(userAns, q.answers)) score++;
            }
        });
        const total = st.listeningData.questions.length;
        const pct = Math.round((score / total) * 100);
        const passageParagraphs = st.listeningData.passage.split('\n\n');

        return (
            <div className="container results-container">
                {/* Results Header */}
                <div className="results-header">
                    <div className="results-header-left">
                        <h1>Analysis & Explanations</h1>
                    </div>
                    <div className="results-header-right">
                        <div className="score-card">
                            <div className="score-number">{score}<span className="score-total">/{total}</span></div>
                            <div className="score-pct">{pct}%</div>
                        </div>
                        <button onClick={() => set('isPassageOpen', !st.isPassageOpen)} className="toggle-passage-btn">
                            {st.isPassageOpen ? '✕ Hide Passage' : '📖 Show Passage'}
                        </button>
                        <button onClick={onReturnHome} className="tool-btn">🏠 Home</button>
                    </div>
                </div>

                {/* Results Body */}
                <div className="results-layout" id="listeningResultsLayout">
                    {/* Passage Sidebar */}
                    <div className={`passage-sidebar ${st.isPassageOpen ? 'open' : ''}`} id="listeningPassageSidebar">
                        <h3>Original Passage</h3>
                        <h4 dangerouslySetInnerHTML={{ __html: formatHighlight(st.listeningData.title) }}></h4>
                        <div className="passage-text">
                            {passageParagraphs.map((p, idx) => (
                                <p key={idx} dangerouslySetInnerHTML={{ __html: formatHighlight(p) }}></p>
                            ))}
                        </div>
                        {st.vocabList.length > 0 && (
                            <div className="result-vocab-list" style={{ marginTop: '24px' }}>
                                <h3>📖 Target Vocabulary</h3>
                                <div className="vocab-chips">
                                    {st.vocabList.map((v, i) => (
                                        <span key={i} className="vocab-chip">
                                            <strong>{v.word}</strong> {v.meaning && `— ${v.meaning}`}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Resizer */}
                    <div className={`resizer ${st.isPassageOpen ? 'active' : ''}`} id="listeningResizerPassage"></div>

                    {/* Analysis Content */}
                    <div className="results-content">
                        {st.listeningData.questions.map((q: any) => {
                            const userAns = userAnswersRef.current[q.id] || 'None';
                            let isCorrect = false;

                            if (isMultipleChoiceMode) {
                                isCorrect = userAns.trim().toUpperCase() === q.answer?.trim().toUpperCase();
                                return (
                                    <div key={q.id} className="result-block">
                                        <div className="question-text">{q.id}. {q.question.replace(/\*\*/g, '')}</div>
                                        {q.options && Object.entries(q.options).map(([k, v]) => (
                                            <div key={k} style={{
                                                marginLeft: '12px',
                                                color: k === q.answer ? '#16a34a' : (k === userAns && !isCorrect ? '#dc2626' : 'inherit'),
                                                fontWeight: k === q.answer ? 'bold' : 'normal'
                                            }}>
                                                {k}. {v as string} {k === q.answer ? ' ✓' : (k === userAns && !isCorrect ? ' ✗' : '')}
                                            </div>
                                        ))}
                                        <p style={{ marginTop: '12px' }}>
                                            Your Answer: <strong className={isCorrect ? 'ans-correct' : 'ans-incorrect'}>{userAns}</strong> | Correct: <strong>{q.answer}</strong>
                                        </p>
                                        <p className={isCorrect ? 'status-correct' : 'status-incorrect'}>
                                            {isCorrect ? '✓ Correct' : '✗ Incorrect'}
                                        </p>
                                        <div className="explanation">
                                            <strong>解析:</strong> {q.explanation}
                                        </div>
                                    </div>
                                );
                            } else {
                                isCorrect = checkAnswer(userAns, q.answers);
                                return (
                                    <div key={q.id} className="result-block">
                                        <div className="question-text">{q.id}. {q.question.replace(/\*\*/g, '')}</div>
                                        <p>Your Answer: <strong className={isCorrect ? 'ans-correct' : 'ans-incorrect'}>{userAns}</strong> | Acceptable: <strong>{q.answers.join(' / ')}</strong></p>
                                        <p className={isCorrect ? 'status-correct' : 'status-incorrect'}>
                                            {isCorrect ? '✓ Correct' : '✗ Incorrect'}
                                        </p>
                                        <div className="explanation">
                                            <strong>解析:</strong> {q.explanation}
                                        </div>
                                    </div>
                                );
                            }
                        })}
                    </div>
                </div>
            </div>
        );
    }

    return null;
}

import AppNavbar from '../components/AppNavbar';
import { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../api/client';
import { showToast } from '../components/Toast';
import '../styles/prompt_page.css';
import '../styles/practice_hub.css';

interface PromptItem {
    id: number;
    username: string;
    prompt_content: string;
    created_at: string;
}

interface PromptResponse {
    data: PromptItem[];
    current_page: number;
    total_pages: number;
    total_count: number;
}

export default function PromptPage() {
    const [prompts, setPrompts] = useState<PromptItem[]>([]);
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [jumpPage, setJumpPage] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    // Form states
    const [newUsername, setNewUsername] = useState('');
    const [newContent, setNewContent] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        fetchPrompts(currentPage);
    }, [currentPage]);

    const fetchPrompts = async (page: number) => {
        setIsLoading(true);
        try {
            const res = await api<PromptResponse>(`/prompts/?page=${page}`);
            setPrompts(res.data);
            setCurrentPage(res.current_page);
            setTotalPages(res.total_pages);
        } catch (error: any) {
            showToast(error.message || '获取提示词失败', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handlePublish = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newUsername.trim() || !newContent.trim()) {
            showToast('用户名和内容不能为空！', 'error');
            return;
        }

        setIsSubmitting(true);
        try {
            await api('/prompts/', {
                method: 'POST',
                body: {
                    username: newUsername.trim(),
                    prompt_content: newContent.trim()
                }
            });
            showToast('发布成功！', 'success');
            setNewContent('');
            // 发布成功后强制回到第一页看最新的
            if (currentPage === 1) {
                fetchPrompts(1);
            } else {
                setCurrentPage(1);
            }
        } catch (err: unknown) {
            console.error('Save prompt error:', err);
            showToast((err as Error).message || '保存失败', 'error', '错误');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleJump = () => {
        const pageNum = parseInt(jumpPage, 10);
        if (!isNaN(pageNum) && pageNum >= 1 && pageNum <= totalPages) {
            setCurrentPage(pageNum);
            setJumpPage('');
        } else {
            showToast(`请输入 1 到 ${totalPages} 之间的有效页码`, 'error');
        }
    };

    // 分页计算核心：基于 current - 2 到 current + 2 的 5 个页面
    const paginationRange = useMemo(() => {
        const range: number[] = [];
        let start = Math.max(1, currentPage - 2);
        let end = Math.min(totalPages, currentPage + 2);

        // 补偿机制：保证始终最多显示 5 个按钮（如果总页数够）
        if (end - start < 4) {
            if (start === 1) {
                end = Math.min(totalPages, 5);
            } else if (end === totalPages) {
                start = Math.max(1, totalPages - 4);
            }
        }

        for (let i = start; i <= end; i++) {
            range.push(i);
        }
        return range;
    }, [currentPage, totalPages]);

    return (
        <div className="practice-hub">
            <AppNavbar />

            <div className="prompt-hub-container">
                <div className="practice-hub-header">
                    <Link to="/practice" className="back-link">← AI Practice</Link>
                    <h1>💡 AI Prompt Hub</h1>
                    <p>分享与查找最绝赞的 AI IELTS 高分提示词密码</p>
                </div>

                <div className="prompt-publish-card">
                    <h3>✍️ 贡献灵感</h3>
                    <form onSubmit={handlePublish} className="prompt-form">
                        <input
                            type="text"
                            placeholder="你的大名 (如: lrhtom)"
                            value={newUsername}
                            onChange={e => setNewUsername(e.target.value)}
                            maxLength={50}
                            required
                        />
                        <textarea
                            placeholder="在这里粘贴你的魔法提示词..."
                            value={newContent}
                            onChange={e => setNewContent(e.target.value)}
                            required
                        />
                        <button type="submit" disabled={isSubmitting}>
                            {isSubmitting ? '发送中...' : '🚀 发布提示词'}
                        </button>
                    </form>
                </div>

                <div className="prompt-list-section">
                    <h3>🏆 社区提示词榜单</h3>
                    {isLoading ? (
                        <div className="prompt-loader">拼命翻找中...</div>
                    ) : prompts.length === 0 ? (
                        <div className="prompt-empty">暂无提示词，快来做第一个发布者吧！</div>
                    ) : (
                        <div className="prompt-grid">
                            {prompts.map(p => (
                                <div key={p.id} className="prompt-card">
                                    <div className="prompt-author">
                                        <span className="author-icon">👤</span> {p.username}
                                    </div>
                                    <div className="prompt-content">
                                        {p.prompt_content}
                                    </div>
                                    <div className="prompt-date">
                                        {new Date(p.created_at).toLocaleDateString()}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* 复杂超级分页器 */}
                {totalPages > 0 && (
                    <div className="super-pagination">
                        <button
                            className="page-btn page-edge"
                            disabled={currentPage === 1}
                            onClick={() => setCurrentPage(1)}>
                            &laquo; 首页
                        </button>
                        <button
                            className="page-btn page-nav"
                            disabled={currentPage === 1}
                            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}>
                            &lsaquo; 上一页
                        </button>

                        <div className="page-numbers">
                            {paginationRange[0] > 1 && <span className="page-ellipsis">...</span>}

                            {paginationRange.map(pageNum => (
                                <button
                                    key={pageNum}
                                    className={`page-btn page-num ${pageNum === currentPage ? 'active' : ''}`}
                                    onClick={() => setCurrentPage(pageNum)}
                                    aria-current={pageNum === currentPage ? "page" : undefined}
                                >
                                    {pageNum}
                                </button>
                            ))}

                            {paginationRange[paginationRange.length - 1] < totalPages && <span className="page-ellipsis">...</span>}
                        </div>

                        <button
                            className="page-btn page-nav"
                            disabled={currentPage === totalPages}
                            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}>
                            下一页 &rsaquo;
                        </button>
                        <button
                            className="page-btn page-edge"
                            disabled={currentPage === totalPages}
                            onClick={() => setCurrentPage(totalPages)}>
                            末页 &raquo;
                        </button>

                        <div className="page-jumper">
                            <span>前往</span>
                            <input
                                type="number"
                                min={1}
                                max={totalPages}
                                value={jumpPage}
                                onChange={(e) => setJumpPage(e.target.value)}
                                onKeyDown={(e) => { if (e.key === 'Enter') handleJump() }}
                            />
                            <span>页</span>
                            <button className="page-btn page-go" onClick={handleJump}>GO</button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

// ReadingPractice.tsx
import { useEffect, useRef, useMemo, useCallback, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { createReadingState } from '../store/reading_page_store';
import type { VocabItem, QuizData } from '../store/reading_page_store';
import { api } from '../api/client';
import { showToast } from '../components/Toast';
import '../styles/reading_page.css';

export default function Reading_page() {
    const { state } = useLocation();
    const vocabInput: string = state?.vocabInput ?? '';
    const difficulty: string = state?.difficulty ?? '7.0';
    const navigate = useNavigate();
    const onReturnHome = () => navigate('/');

    // 用单一 useState 替代 reactive store
    const [st, setSt] = useState(createReadingState);
    const set = <K extends keyof typeof st>(k: K, v: typeof st[K]) =>
        setSt(s => ({ ...s, [k]: v }));

    // DOM refs
    const userAnswersRef = useRef<Record<number, string>>({});
    const hasRequested = useRef(false);
    const leftSidebarRef = useRef<HTMLDivElement | null>(null);
    const rightSidebarRef = useRef<HTMLDivElement | null>(null);
    const layoutRef = useRef<HTMLDivElement | null>(null);
    const floatBtnRef = useRef<HTMLDivElement | null>(null);
    const activeEditorRef = useRef<HTMLElement | null>(null);

    useEffect(() => {
        if (hasRequested.current) return;
        hasRequested.current = true;
        setSt(createReadingState());
        generateReading();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [set]); // Added 'set' to dependencies

    const formatHighlight = (text: string): string => {
        if (!text) return '';
        return text.replace(/\*\*(.*?)\*\*/g, '<span class="highlight">$1</span>');
    };

    const generateReading = async () => {
        // 解析词汇
        const parsedList: VocabItem[] = vocabInput.trim().split('\n').map(line => {
            const parts = line.split(/[-:]/);
            return {
                word: parts[0] ? parts[0].trim() : '',
                meaning: parts[1] ? parts[1].trim() : ''
            };
        }).filter(item => item.word).sort((a, b) => a.word.localeCompare(b.word));

        set('vocabList', parsedList);
        const words = parsedList.map(v => v.word);

        try {
            // 调用后端 API，不再直接调 AI
            const parsedData = await api<QuizData>('/reading/generate', {
                method: 'POST',
                body: { words, difficulty },
            });

            set('quizData', parsedData);
            userAnswersRef.current = {};
            set('searchQuery', '');
            set('isLeftOpen', true);
            set('isRightOpen', true);
            set('startTime', Date.now());
            set('elapsedSeconds', 0);

            const pageEl = document.getElementById('reading-page-container');
            const btnEl = document.getElementById('highlight-toggle-btn');
            if (pageEl) pageEl.classList.remove('hide-highlights');
            if (btnEl) {
                btnEl.innerText = '💡 Hide Target Words';
                btnEl.classList.remove('active');
            }

        } catch (err: unknown) { // Changed 'any' to 'unknown'
            console.error("API Error:", err);
            const error = err as { message?: string, status?: number }; // Cast to a type that might have message and status
            const code = error.status ?? (err instanceof TypeError ? 'NET' : undefined);
            showToast(error.message || '请求失败', 'error', code);
            onReturnHome();
        } finally {
            set('isLoading', false);
        }
    };

    const toggleHighlightsPureDOM = () => {
        const pageEl = document.getElementById('reading-page-container');
        const btnEl = document.getElementById('highlight-toggle-btn');
        if (pageEl && btnEl) {
            const isHidden = pageEl.classList.contains('hide-highlights');
            if (isHidden) {
                pageEl.classList.remove('hide-highlights');
                btnEl.innerText = '💡 Hide Target Words';
                btnEl.classList.remove('active');
            } else {
                pageEl.classList.add('hide-highlights');
                btnEl.innerText = '💡 Show Target Words';
                btnEl.classList.add('active');
            }
        }
    };

    const submitQuiz = () => {
        if (!st.quizData) return;
        const totalQuestions = st.quizData.questions.length;
        const answeredQuestions = Object.keys(userAnswersRef.current).length;
        if (answeredQuestions < totalQuestions) {
            if (!window.confirm('You have unanswered questions. Submit anyway?')) return;
        }
        set('step', 3);
    };

    // Timer helper
    const formatTime = useCallback((totalSeconds: number) => {
        const h = Math.floor(totalSeconds / 3600);
        const m = Math.floor((totalSeconds % 3600) / 60);
        const s = totalSeconds % 60;
        return {
            h: String(h).padStart(2, '0'),
            m: String(m).padStart(2, '0'),
            s: String(s).padStart(2, '0'),
        };
    }, []);

    // Timer tick effect
    useEffect(() => {
        if (st.step !== 2 || st.isLoading || !st.startTime) return;
        const interval = setInterval(() => {
            set('elapsedSeconds', Math.floor((Date.now() - st.startTime) / 1000));
        }, 1000);
        return () => clearInterval(interval);
    }, [st.step, st.isLoading, st.startTime]);

    // Resizer Logic
    useEffect(() => {
        if (st.step !== 2 || st.isLoading) return;
        const resizerL = document.getElementById('resizerLeft');
        const resizerR = document.getElementById('resizerRight');
        let isResizingLeft = false, isResizingRight = false, startX = 0, startWidth = 0;

        const handleMouseDownLeft = (e: MouseEvent) => {
            isResizingLeft = true; startX = e.clientX;
            if (leftSidebarRef.current) startWidth = leftSidebarRef.current.getBoundingClientRect().width;
            if (layoutRef.current) layoutRef.current.classList.add('is-resizing');
            if (resizerL) resizerL.classList.add('resizing');
        };

        const handleMouseDownRight = (e: MouseEvent) => {
            isResizingRight = true; startX = e.clientX;
            if (rightSidebarRef.current) startWidth = rightSidebarRef.current.getBoundingClientRect().width;
            if (layoutRef.current) layoutRef.current.classList.add('is-resizing');
            if (resizerR) resizerR.classList.add('resizing');
        };

        const handleMouseMove = (e: MouseEvent) => {
            if (!isResizingLeft && !isResizingRight) return;
            if (isResizingLeft && leftSidebarRef.current) {
                const newWidth = startWidth + (e.clientX - startX);
                if (newWidth > 150 && newWidth < window.innerWidth * 0.4) leftSidebarRef.current.style.width = newWidth + 'px';
            } else if (isResizingRight && rightSidebarRef.current) {
                const newWidth = startWidth - (e.clientX - startX);
                if (newWidth > 150 && newWidth < window.innerWidth * 0.4) rightSidebarRef.current.style.width = newWidth + 'px';
            }
        };

        const handleMouseUp = () => {
            if (isResizingLeft || isResizingRight) {
                // @ts-expect-error window globals
                window.__didDragSidebar = true;
                // 拖动结束后禁用 transition 防止跳动
                if (isResizingLeft && leftSidebarRef.current) leftSidebarRef.current.classList.add('no-transition');
                if (isResizingRight && rightSidebarRef.current) rightSidebarRef.current.classList.add('no-transition');
                isResizingLeft = false; isResizingRight = false;
                if (layoutRef.current) layoutRef.current.classList.remove('is-resizing');
                if (resizerL) resizerL.classList.remove('resizing');
                if (resizerR) resizerR.classList.remove('resizing');
                // @ts-expect-error window globals
                setTimeout(() => { window.__didDragSidebar = false; }, 200);
            }
        };

        resizerL?.addEventListener('mousedown', handleMouseDownLeft);
        resizerR?.addEventListener('mousedown', handleMouseDownRight);
        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);

        return () => {
            resizerL?.removeEventListener('mousedown', handleMouseDownLeft);
            resizerR?.removeEventListener('mousedown', handleMouseDownRight);
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };
    }, [st.step, st.isLoading]);

    // Floating Underline Logic
    useEffect(() => {
        if (st.step !== 2 || st.isLoading) return;
        const handleGlobalMouseUp = (e: MouseEvent) => {
            if (layoutRef.current?.classList.contains('is-resizing')) return;
            const target = e.target as HTMLElement;
            const isArticle = target.closest('#articleContent');
            const isQuestions = target.closest('#questionsForm');

            if (!isArticle && !isQuestions) {
                if (floatBtnRef.current) floatBtnRef.current.classList.remove('visible');
                return;
            }

            const selection = window.getSelection();
            const selectedText = selection?.toString().trim() || '';

            if (selectedText.length > 0) {
                activeEditorRef.current = isArticle ? document.getElementById('articleContent') : document.getElementById('questionsForm');
                if (floatBtnRef.current) {
                    floatBtnRef.current.classList.add('visible');
                    floatBtnRef.current.style.left = (e.pageX + 15) + 'px';
                    floatBtnRef.current.style.top = (e.pageY - 40) + 'px';
                }
            } else {
                if (floatBtnRef.current) floatBtnRef.current.classList.remove('visible');
            }
        };

        const handleGlobalMouseDown = (e: MouseEvent) => {
            const target = e.target as HTMLElement;
            if (target !== floatBtnRef.current && !target.classList.contains('resizer')) {
                if (floatBtnRef.current) floatBtnRef.current.classList.remove('visible');
            }
        };

        document.body.addEventListener('mouseup', handleGlobalMouseUp);
        document.addEventListener('mousedown', handleGlobalMouseDown);
        return () => {
            document.body.removeEventListener('mouseup', handleGlobalMouseUp);
            document.removeEventListener('mousedown', handleGlobalMouseDown);
        };
    }, [st.step, st.isLoading]);

    const executeUnderline = () => {
        if (!activeEditorRef.current) return;
        activeEditorRef.current.contentEditable = 'true';
        document.execCommand('underline', false, '');
        activeEditorRef.current.contentEditable = 'false';
        if (floatBtnRef.current) floatBtnRef.current.classList.remove('visible');
        window.getSelection()?.removeAllRanges();
    };

    // Resizer for results passage sidebar
    useEffect(() => {
        const sidebar = document.getElementById('passageSidebar');
        if (!st.isPassageOpen) {
            if (sidebar) sidebar.style.width = '';
            return;
        }
        if (st.step !== 3) return;
        const resizer = document.getElementById('resizerPassage');
        const layout = document.getElementById('resultsLayout');
        if (!resizer || !sidebar || !layout) return;

        let isResizing = false, startX = 0, startWidth = 0;

        const onMouseDown = (e: MouseEvent) => {
            isResizing = true;
            startX = e.clientX;
            startWidth = sidebar.getBoundingClientRect().width;
            layout.classList.add('is-resizing');
            resizer.classList.add('resizing');
        };
        const onMouseMove = (e: MouseEvent) => {
            if (!isResizing) return;
            const newWidth = startWidth + (e.clientX - startX);
            if (newWidth > 200 && newWidth < window.innerWidth * 0.55) {
                sidebar.style.width = newWidth + 'px';
            }
        };
        const onMouseUp = () => {
            if (isResizing) {
                isResizing = false;
                layout.classList.remove('is-resizing');
                resizer.classList.remove('resizing');
            }
        };

        resizer.addEventListener('mousedown', onMouseDown);
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
        return () => {
            resizer.removeEventListener('mousedown', onMouseDown);
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [st.step, st.isPassageOpen]);

    // Memoized Blocks
    const articleMemoBlock = useMemo(() => {
        if (!st.quizData) return null;
        const passageParagraphs = st.quizData.passage.split('\n\n');
        return (
            <div className="main-content">
                <h2 style={{ marginTop: 0 }} dangerouslySetInnerHTML={{ __html: formatHighlight(st.quizData.title) }}></h2>
                <div
                    id="articleContent"
                    style={{ outline: 'none', WebkitTouchCallout: 'none' }}
                    onContextMenu={(e) => e.preventDefault()}
                >
                    {passageParagraphs.map((p, idx) => (
                        <p key={idx} dangerouslySetInnerHTML={{ __html: formatHighlight(p) }}></p>
                    ))}
                </div>
            </div>
        );
    }, [st.quizData]);

    const questionsMemoBlock = useMemo(() => {
        if (!st.quizData) return null;
        return (
            <div id="questionsForm" style={{ outline: 'none', WebkitTouchCallout: 'none' }} onContextMenu={(e) => e.preventDefault()}>
                {st.quizData.questions.map((q) => (
                    <div key={q.id} className="question-block">
                        <div className="question-text" dangerouslySetInnerHTML={{ __html: `${q.id}. ${formatHighlight(q.question)}` }}></div>
                        {Object.entries(q.options).map(([key, value]) => (
                            <label key={key} className="option-label">
                                <input
                                    type="radio" name={`q${q.id}`} value={key}
                                    defaultChecked={userAnswersRef.current[q.id] === key}
                                    onChange={() => { userAnswersRef.current[q.id] = key; }}
                                />
                                <strong>{key}.</strong> <span dangerouslySetInnerHTML={{ __html: formatHighlight(value) }}></span>
                            </label>
                        ))}
                    </div>
                ))}
            </div>
        );
    }, [st.quizData]);

    // Loading State
    if (st.isLoading) {
        return (
            <div className="container">
                <div className="page" style={{ justifyContent: 'center', alignItems: 'center' }}>
                    <div className="loader">AI is writing your IELTS {difficulty} level passage... Please wait.</div>
                </div>
            </div>
        );
    }

    // Page 2: Reading Interface
    if (st.step === 2 && st.quizData) {
        const filteredVocab = st.vocabList.filter(v =>
            v.word.toLowerCase().includes(st.searchQuery.toLowerCase()) ||
            v.meaning.toLowerCase().includes(st.searchQuery.toLowerCase())
        );

        return (
            <div className="container reading-container">
                <div id="floatUnderlineBtn" ref={floatBtnRef} onMouseDown={(e) => e.preventDefault()} onClick={executeUnderline}>
                    <u>U</u> Underline
                </div>

                <div id="reading-page-container" className="page">
                    <div className="toolbar-area">
                        <div>
                            <button onClick={() => { if ((window as any).__didDragSidebar) return; if (leftSidebarRef.current) { leftSidebarRef.current.classList.remove('no-transition'); leftSidebarRef.current.style.width = ''; } set('isLeftOpen', !st.isLeftOpen); }}>☰ Dictionary</button>
                            <span style={{ margin: '0 5px' }}></span>
                            <button onClick={() => { if ((window as any).__didDragSidebar) return; if (rightSidebarRef.current) { rightSidebarRef.current.classList.remove('no-transition'); rightSidebarRef.current.style.width = ''; } set('isRightOpen', !st.isRightOpen); }}>✎ Questions</button>
                        </div>
                        <div className="reading-timer">
                            <span className="timer-icon">🕐</span>
                            <span className="timer-label">time</span>
                            <span className="timer-digit">{formatTime(st.elapsedSeconds).h}</span>
                            <span className="timer-sep">:</span>
                            <span className="timer-digit">{formatTime(st.elapsedSeconds).m}</span>
                            <span className="timer-sep">:</span>
                            <span className="timer-digit">{formatTime(st.elapsedSeconds).s}</span>
                        </div>
                        <div>
                            <button
                                id="highlight-toggle-btn"
                                className="tool-btn"
                                onClick={toggleHighlightsPureDOM}
                            >
                                💡 Hide Target Words
                            </button>
                        </div>
                    </div>

                    <div className="reading-layout" ref={layoutRef}>
                        {/* Left Sidebar */}
                        <div id="leftSidebar" ref={leftSidebarRef} className={`sidebar ${st.isLeftOpen ? 'open' : ''}`}>
                            <h2 style={{ marginTop: 0 }}>Vocabulary</h2>
                            <input
                                type="text" id="vocabSearch" placeholder="🔍 Search word or meaning..."
                                value={st.searchQuery} onChange={(e) => set('searchQuery', e.target.value)}
                            />
                            <div>
                                {filteredVocab.map((v, idx) => (
                                    <p key={idx}>
                                        <strong>{v.word}</strong><br />
                                        <span style={{ fontSize: '14px', color: '#555' }}>{v.meaning}</span>
                                    </p>
                                ))}
                            </div>
                        </div>

                        <div className={`resizer ${st.isLeftOpen ? 'active' : ''}`} id="resizerLeft"></div>
                        {articleMemoBlock}
                        <div className={`resizer ${st.isRightOpen ? 'active' : ''}`} id="resizerRight"></div>

                        {/* Right Sidebar */}
                        <div id="rightSidebar" ref={rightSidebarRef} className={`sidebar ${st.isRightOpen ? 'open' : ''}`}>
                            <h2 style={{ marginTop: 0 }}>Questions</h2>
                            {questionsMemoBlock}
                            <div className="submit-quiz-container">
                                <button onClick={submitQuiz}>Submit Answers</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // Page 3: Results
    if (st.step === 3 && st.quizData) {
        let score = 0;
        st.quizData.questions.forEach(q => {
            if (userAnswersRef.current[q.id] === q.answer) score++;
        });
        const total = st.quizData.questions.length;
        const pct = Math.round((score / total) * 100);
        const passageParagraphs = st.quizData.passage.split('\n\n');

        return (
            <div className="container results-container">
                {/* Results Header */}
                <div className="results-header">
                    <div className="results-header-left">
                        <h1>Analysis & Explanations</h1>
                        <p className="elapsed-time">
                            🕐 {formatTime(st.elapsedSeconds).h}h {formatTime(st.elapsedSeconds).m}m {formatTime(st.elapsedSeconds).s}s
                        </p>
                    </div>
                    <div className="results-header-right">
                        <div className="score-card">
                            <div className="score-number">{score}<span className="score-total">/{total}</span></div>
                            <div className="score-pct">{pct}%</div>
                        </div>
                        <button onClick={() => set('isPassageOpen', !st.isPassageOpen)} className="toggle-passage-btn">
                            {st.isPassageOpen ? '✕ Hide Passage' : '📖 Show Passage'}
                        </button>
                        <button onClick={onReturnHome} className="tool-btn">🏠 Home</button>
                    </div>
                </div>

                {/* Results Body */}
                <div className="results-layout" id="resultsLayout">
                    {/* Passage Sidebar */}
                    <div className={`passage-sidebar ${st.isPassageOpen ? 'open' : ''}`} id="passageSidebar">
                        <h3>Original Passage</h3>
                        <h4 dangerouslySetInnerHTML={{ __html: formatHighlight(st.quizData.title) }}></h4>
                        <div className="passage-text">
                            {passageParagraphs.map((p, idx) => (
                                <p key={idx} dangerouslySetInnerHTML={{ __html: formatHighlight(p) }}></p>
                            ))}
                        </div>
                    </div>

                    {/* Resizer */}
                    <div className={`resizer ${st.isPassageOpen ? 'active' : ''}`} id="resizerPassage"></div>

                    {/* Analysis Content */}
                    <div className="results-content">
                        {st.quizData.questions.map(q => {
                            const userAns = userAnswersRef.current[q.id] || 'None';
                            const isCorrect = userAns === q.answer;

                            return (
                                <div key={q.id} className="result-block">
                                    <div className="question-text">{q.id}. {q.question.replace(/\*\*/g, '')}</div>
                                    <p>Your Answer: <strong className={isCorrect ? 'ans-correct' : 'ans-incorrect'}>{userAns}</strong> | Correct Answer: <strong>{q.answer}</strong></p>
                                    <p className={isCorrect ? 'status-correct' : 'status-incorrect'}>
                                        {isCorrect ? '✓ Correct' : '✗ Incorrect'}
                                    </p>
                                    <div className="explanation">
                                        <strong>解析:</strong> {q.explanation}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        );
    }

    return null;
}

/**
 * SpeakingChatPage — 口语聊天练习页
 *
 * 架构:
 *  1. 前端 SpeechRecognition API  → 识别用户说的话（文本）
 *  2. 文本 → POST /api/speaking/chat → AI 回复文本
 *  3. AI 文本 → POST /api/listening/audio (edge-tts) → 音频 blob
 *  4. 前端播放音频 → 播放完毕 → 解锁录音按钮
 *
 * 状态机:
 *  idle       → 可以点击录音
 *  listening  → 正在录音（SpeechRecognition 运行中）
 *  speaking   → 播放 AI 语音（禁用按钮）
 *  loading    → 进入页面时欢迎语加载（禁用按钮）
 */
import { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import RecordRTC, { StereoAudioRecorder } from 'recordrtc';
import { speakingStore } from '../store/speaking_page_store';
import AiModelSelector from '../components/AiModelSelector';
import { ATInterceptor } from '../api/atInterceptor';
import { showToast } from '../components/Toast';
import '../styles/speaking_chat.css';

// ── Types ──────────────────────────────────────────────────────────────────
type Role = 'user' | 'assistant' | 'system';
interface ChatMessage {
    role: Role;
    content: string;
    scores?: {
        grammar?: number;
        vocab?: number;
        relevance?: number;
        accuracy?: number;
        pronunciation?: number;
        completeness?: number;
        fluency?: number;
    };
}

type Status = 'loading' | 'mic_loading' | 'idle' | 'listening' | 'processing' | 'speaking';

interface Word {
    en: string;
    zh?: string;
    count: number;
}

// ── Helpers ────────────────────────────────────────────────────────────────
function parseWords(raw: string): Word[] {
    if (!raw.trim()) return [];
    return raw.split('\n')
        .map(l => l.trim())
        .filter(l => l)
        .map(l => {
            const m = l.match(/^([a-zA-Z\s-]+)(.*)$/);
            if (!m) return null;
            return { en: m[1].trim(), zh: m[2].trim(), count: 0 };
        })
        .filter(Boolean) as Word[];
}

function countMatches(text: string, word: string): number {
    const rx = new RegExp(`\\b${word}\\b`, 'gi');
    return (text.match(rx) || []).length;
}

function highlightWords(text: string, words: Word[]): string {
    let out = text;
    words.forEach(w => {
        if (!w.en) return;
        const rx = new RegExp(`\\b(${w.en})\\b`, 'gi');
        out = out.replace(rx, '<span class="sc-highlight">$1</span>');
    });
    return out;
}

// SpeechRecognition cross-browser factory (avoids TypeScript global type issues)
const getSRConstructor = (): any =>
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition || null;

export default function SpeakingChatPage() {
    const location = useLocation();
    const navigate = useNavigate();
    const vocabRaw: string = (location.state as { vocabInput?: string })?.vocabInput ?? '';

    // ── 路由守卫：防止刷新或直接跳转进来 ────────────────────────────────────
    useEffect(() => {
        if (!speakingStore.isChatAllowed) {
            navigate('/speaking', { replace: true });
            return;
        }

        return () => {
            // 组件卸载时，无论是由于 React v18 开发模式严苛双重调用，还是真的离开路由
            // 都在事件循环后置空合规性变量。这样外部跳转返回时就被封禁了。
            setTimeout(() => {
                speakingStore.isChatAllowed = false;
            }, 0);
        };
    }, [navigate]);

    // ── State ──
    const [words, setWords] = useState<Word[]>(() => parseWords(vocabRaw));
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [status, setStatus] = useState<Status>('loading');
    const [liveTranscript, setLiveTranscript] = useState('');
    const [recError, setRecError] = useState('');
    const [audioLevel, setAudioLevel] = useState(0);
    const [recordingTime, setRecordingTime] = useState(0);

    // ── Refs (never stale inside callbacks) ──
    const wordsRef = useRef<Word[]>(parseWords(vocabRaw));
    const contextRef = useRef<ChatMessage[]>([]);
    const statusRef = useRef<Status>('loading');
    const audioRef = useRef<HTMLAudioElement | null>(null);
    const ttsTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const recTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
    // Prevent concurrent handleSend calls
    const pendingRef = useRef(false);

    // AudioContext for volume visualizer
    const audioCtxRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const animFrameRef = useRef<number | null>(null);
    const micStreamRef = useRef<MediaStream | null>(null);

    // Frontend live transcript engine
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const srRef = useRef<any>(null);
    // Background WAV engine for backend debug
    const recorderRef = useRef<RecordRTC | null>(null);

    const setStatusSync = (s: Status) => { statusRef.current = s; setStatus(s); };
    const setWordsSync = (fn: (p: Word[]) => Word[]) => {
        setWords(prev => { const n = fn(prev); wordsRef.current = n; return n; });
    };

    // ── Init: play welcome then unlock mic ─────────────────────────────────
    useEffect(() => {
        // 重置所有状态到初始值，防止从其他页面返回时残留旧数据
        setStatusSync('loading');
        setChatHistory([]);
        setLiveTranscript('');
        setRecError('');
        setAudioLevel(0);
        setRecordingTime(0);
        pendingRef.current = false;

        // 【新增】进页面立刻索要麦克风权限
        navigator.mediaDevices.getUserMedia({ audio: true })
            .then(stream => {
                // 成功授权后，立刻释放掉这些轨道，免得浏览器右上角一直有个红点（真正用的时候会再次请求）
                stream.getTracks().forEach(track => track.stop());
            })
            .catch(err => {
                console.warn('初次请求麦克风权限被拒或出错:', err);
                // 此时并不强行报错中断流程（因为用户点按钮时还会再次申请并抛错）
            });

        const wordList = wordsRef.current.map(w => w.en).join(', ');
        const systemPrompt = `You are an IELTS speaking practice AI examiner.
Target vocabulary: [${wordList}].
Rules:
1. Always reply in English only.
2. Use the target vocabulary naturally in your responses.
3. Keep replies concise (1-3 sentences).
4. No markdown symbols.
5. Encourage the user to use the target words.`;

        contextRef.current = [{ role: 'system', content: systemPrompt }];

        let isUnmounted = false;

        (async () => {
            // TTS removed for stub
            if (!isUnmounted) setStatusSync('idle');
        })();

        return () => {
            isUnmounted = true;
            stopAudio();
            if (srRef.current) {
                try { srRef.current.abort(); } catch { /* ignore */ }
            }
            if (recorderRef.current) {
                recorderRef.current.destroy();
                recorderRef.current = null;
            }
            micStreamRef.current?.getTracks().forEach(t => t.stop());
            if (recTimerRef.current) clearInterval(recTimerRef.current);
            if (ttsTimerRef.current) clearTimeout(ttsTimerRef.current);
        };

    }, []);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [chatHistory, liveTranscript]);

    // Because uploading transcript takes time, use refs
    const liveTranscriptRef = useRef('');
    useEffect(() => { liveTranscriptRef.current = liveTranscript; }, [liveTranscript]);

    // ── Audio visualizer ──────────────────────────────────────────────────
    const setupAudioVisualizer = async () => {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        micStreamRef.current = stream;
        const ctx = new AudioContext();
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 256;
        ctx.createMediaStreamSource(stream).connect(analyser);
        audioCtxRef.current = ctx;
        analyserRef.current = analyser;
        const buf = new Uint8Array(analyser.frequencyBinCount);
        const tick = () => {
            analyser.getByteFrequencyData(buf);
            setAudioLevel(Math.min(100, (buf.reduce((a, b) => a + b, 0) / buf.length) * 2.5));
            animFrameRef.current = requestAnimationFrame(tick);
        };
        animFrameRef.current = requestAnimationFrame(tick);
    };
    const stopAudioVisualizer = () => {
        if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
        animFrameRef.current = null;
        setAudioLevel(0);
        micStreamRef.current?.getTracks().forEach(t => t.stop());
        micStreamRef.current = null;
    };

    // ── Recording timer ───────────────────────────────────────────────────
    const startRecTimer = () => {
        setRecordingTime(0);
        recTimerRef.current = setInterval(() => setRecordingTime(t => t + 1), 1000);
    };
    const stopRecTimer = () => {
        if (recTimerRef.current) { clearInterval(recTimerRef.current); recTimerRef.current = null; }
        setRecordingTime(0);
    };

    // ── RecordRTC upload logic (Background Debug Only) ───────────────────
    const uploadRecording = async (blob: Blob, text: string) => {
        try {
            const formData = new FormData();
            formData.append('audio', blob, 'speaking.wav');
            if (text) {
                formData.append('reference_text', text);
            }

            const res = await fetch(`${import.meta.env.VITE_API_BASE}/api/speaking/transcribe`, {
                method: 'POST',
                body: formData,
            });
            if (!res.ok) return null;
            const data = await res.json();
            return data.scores || null;
        } catch (err) {
            console.error('上传录音进行评估失败', err);
            return null;
        }
    };

    // ── Toggle recording ──────────────────────────────────────────────────
    const toggleRecording = async () => {
        const s = statusRef.current;
        if (s === 'loading' || s === 'mic_loading' || s === 'processing' || s === 'speaking') return;

        if (s === 'idle') {
            // Start
            setStatusSync('mic_loading');
            setRecError('');
            setLiveTranscript('');
            liveTranscriptRef.current = '';

            // Setup Frontend SR
            const SR = getSRConstructor();
            if (!SR) {
                setRecError('浏览器不支持语音识别，请使用 Chrome 浏览器或 Edge');
                setStatusSync('idle');
                return;
            }
            const sr = new SR();
            sr.lang = 'en-US';
            sr.continuous = true;
            sr.interimResults = true;
            sr.maxAlternatives = 1;

            let accumulatedFinal = '';

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            sr.onresult = (e: any) => {
                let interim = '';
                for (let i = e.resultIndex; i < e.results.length; i++) {
                    if (e.results[i].isFinal) {
                        accumulatedFinal += e.results[i][0].transcript + ' ';
                    } else {
                        interim += e.results[i][0].transcript;
                    }
                }
                const t = (accumulatedFinal + interim).trim();
                setLiveTranscript(t);
                liveTranscriptRef.current = t;
            };

            // Guard: onend fires only once
            let onendHandled = false;
            sr.onend = () => {
                if (onendHandled) return;
                if (statusRef.current !== 'listening' && statusRef.current !== 'processing') return;
                onendHandled = true;

                stopAudioVisualizer();
                stopRecTimer();
                const text = liveTranscriptRef.current.trim();
                setLiveTranscript('');
                liveTranscriptRef.current = '';

                // Also stop the background WAV recorder
                if (recorderRef.current) {
                    recorderRef.current.stopRecording(() => {
                        const blob = recorderRef.current!.getBlob();
                        recorderRef.current!.reset();
                        recorderRef.current!.destroy();
                        recorderRef.current = null;

                        if (text) {
                            handleSend(text, blob.size > 1000 ? blob : undefined);
                        } else {
                            setRecError('未能识别到语音，请大声重试');
                            setStatusSync('idle');
                        }
                    });
                } else {
                    if (text) {
                        handleSend(text);
                    } else {
                        setRecError('未能识别到语音，请大声重试');
                        setStatusSync('idle');
                    }
                }
            };

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            sr.onerror = (e: any) => {
                console.log('sr.onerror', e);
                if (e.error === 'aborted') return;
                if (e.error === 'network' && statusRef.current === 'processing') return;

                stopAudioVisualizer();
                stopRecTimer();
                if (e.error === 'no-speech') {
                    setRecError('没有检测到语音，请重试');
                } else if (e.error === 'network') {
                    setRecError('语音识别需要网络，请检查连接');
                } else if (e.error === 'not-allowed') {
                    setRecError('麦克风权限被拒绝，请允许后刷新');
                } else {
                    setRecError(`识别错误: ${e.error}`);
                }
                setStatusSync('idle');

                // Clear the background recorder if SR fails early
                if (recorderRef.current) {
                    recorderRef.current.stopRecording();
                    recorderRef.current.destroy();
                    recorderRef.current = null;
                }
            };

            srRef.current = sr;

            try {
                // 1. 获取麦克风权限
                await setupAudioVisualizer();
                if (!micStreamRef.current) throw new Error('No stream');

                // 2. 准备后台纯正 WAV 录音库
                const recorder = new RecordRTC(micStreamRef.current, {
                    type: 'audio',
                    mimeType: 'audio/wav',
                    recorderType: StereoAudioRecorder,
                    numberOfAudioChannels: 1,
                    desiredSampRate: 16000,
                });

                // 3. 当浏览器前端 STT 连通时触发
                sr.onstart = () => {
                    if (statusRef.current === 'mic_loading') {
                        recorder.startRecording();
                        recorderRef.current = recorder;
                        setStatusSync('listening');
                        startRecTimer();
                    }
                };

                sr.start();
            } catch {
                setRecError('麦克风权限被拒绝或无法启动，请检查浏览器设置');
                setStatusSync('idle');
            }

        } else if (s === 'listening') {
            // Stop manually
            setStatusSync('processing');
            // This implicitly calls sr.onend
            try { srRef.current?.stop(); } catch { /* ignore */ }
        }
    };

    // ── Send text to AI ───────────────────────────────────────────────────
    const handleSend = async (text: string, audioBlob?: Blob) => {
        if (!text) { setStatusSync('idle'); return; }
        // Prevent concurrent requests (e.g. double onend firing)
        if (pendingRef.current) return;
        pendingRef.current = true;

        const userMsg: ChatMessage = { role: 'user', content: text };
        setChatHistory(h => [...h, userMsg]);
        setWordsSync(prev => prev.map(w => ({ ...w, count: w.count + countMatches(text, w.en) })));
        setStatusSync('processing');

        const unusedWords = wordsRef.current.filter(w => w.count === 0).map(w => w.en);
        const messages: ChatMessage[] = [...contextRef.current, userMsg];
        if (unusedWords.length > 0) {
            messages.push({
                role: 'system',
                content: `[Reminder] User hasn't used: "${unusedWords.slice(0, 4).join(', ')}". Use 1-2 naturally.`,
            });
        }

        try {
            const chatPromise = ATInterceptor.speakingChat(
                messages as unknown as Array<Record<string, unknown>>,
                { conversationLength: 1 } // 每回合消耗
            );
            const uploadPromise = audioBlob ? uploadRecording(audioBlob, text) : Promise.resolve(null);

            const [chatResponse] = await Promise.all([chatPromise, uploadPromise]);

            const chatRes = chatResponse.data;

            const aiMsg: ChatMessage = {
                role: 'assistant',
                content: chatRes.reply,
                scores: {
                    grammar: chatRes.grammar_score,
                    vocab: chatRes.vocab_score,
                    relevance: chatRes.relevance_score,
                }
            };
            setChatHistory(h => [...h, aiMsg]);
            contextRef.current = [...contextRef.current, userMsg, { role: 'assistant', content: chatRes.reply }];
            setWordsSync(prev => prev.map(w => ({ ...w, count: w.count + countMatches(chatRes.reply, w.en) })));

            // Play audio stub
            setTimeout(() => {
                pendingRef.current = false;
                setStatusSync('idle');
            }, 100);

        } catch (error: unknown) {
            pendingRef.current = false;

            // 区分AT币不足错误和一般网络错误
            if (typeof error === 'object' && error !== null && ('name' in error && (error as { name: string }).name === 'ATBalanceError' || 'message' in error && (error as { message: string }).message === 'AT币余额不足')) {
                showToast((error as { message: string }).message, 'error', 'AT币不足');
                setChatHistory(h => [...h, { role: 'system', content: '⚠️ AT币余额不足，请充值或联系管理员' }]);
            } else {
                setChatHistory(h => [...h, { role: 'system', content: '⚠️ AI 连接失败，请检查网络后重试' }]);
            }
            setStatusSync('idle');
        }
    };

    // ── TTS: remove functionality ─────────────────────────
    const stopAudio = () => {
        const timer = ttsTimerRef.current;
        if (timer) clearTimeout(timer);
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current.onended = null;
            audioRef.current.onerror = null;
            audioRef.current = null;
        }
        window.speechSynthesis?.cancel();
    };

    // ── UI helpers ─────────────────────────────────────────────────────────
    const STATUS_LABEL: Record<Status, string> = {
        loading: '加载中...',
        mic_loading: '请求麦克风权限...',
        idle: '可以说话了',
        listening: '录音中...',
        processing: 'AI 思考中...',
        speaking: 'AI 说话中...',
    };
    const MIC_LABEL: Record<Status, string> = {
        loading: '加载中，请稍候...',
        mic_loading: '🎙️ 加载麦克风...',
        idle: '🎙️ 按下开始说话',
        listening: '🔴 点击结束说话',
        processing: '⏳ AI 思考中...',
        speaking: '🔊 AI 说话中...',
    };
    const formatTime = (s: number) =>
        `${Math.floor(s / 60).toString().padStart(2, '0')}:${(s % 60).toString().padStart(2, '0')}`;

    const BAR_COUNT = 12;
    const isDisabled = status === 'loading' || status === 'mic_loading' || status === 'processing' || status === 'speaking';

    return (
        <div className="sc-root">
            {/* ── Sidebar: Word Basket & Ai Settings ── */}
            <aside className="sc-sidebar">
                <div className="sc-sidebar-header">
                    <button className="sc-back-btn" onClick={() => navigate('/speaking')}>← 返回</button>
                    <h3>📚 词汇 & 设置</h3>
                </div>

                <div style={{ padding: '0 1rem 1rem 1rem', borderBottom: '1px solid var(--border-color)', marginBottom: '1rem' }}>
                    <AiModelSelector label="当前模型" description="" />
                </div>

                <div className="sc-word-list">
                    {words.length === 0 && <p className="sc-no-words">暂无目标词汇</p>}
                    {words.map((w, i) => (
                        <div key={i} className={`sc-word-item${w.count > 0 ? ' used' : ''}`}>
                            <div className="sc-word-text">
                                <span className="sc-word-en">{w.en}</span>
                                {w.zh && <span className="sc-word-zh">{w.zh}</span>}
                            </div>
                            {w.count > 0 && <span className="sc-word-count">{w.count}</span>}
                        </div>
                    ))}
                </div>
            </aside>

            {/* ── Chat Area ── */}
            <main className="sc-main">
                <div className="sc-messages">
                    {chatHistory.map((msg, i) => (
                        <div key={i} className={`sc-bubble-wrapper ${msg.role}`}>
                            <div className={`sc-bubble sc-bubble-${msg.role}`}>
                                {msg.role === 'assistant' ? (
                                    <span dangerouslySetInnerHTML={{ __html: highlightWords(msg.content, words) }} />
                                ) : msg.role === 'system' ? (
                                    <span className="sc-system-msg">{msg.content}</span>
                                ) : (
                                    <span>{msg.content}</span>
                                )}
                            </div>

                            {msg.scores && (
                                <details className="sc-score-panel">
                                    <summary>
                                        🌟 查看本轮口语多维评分详情
                                    </summary>
                                    <div className="sc-score-details">
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">🎯 准确度 (Accuracy):</span>
                                            <span className="sc-score-value">{msg.scores.accuracy ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">👄 发音 (Pronunciation):</span>
                                            <span className="sc-score-value">{msg.scores.pronunciation ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">🌊 流利度 (Fluency):</span>
                                            <span className="sc-score-value">{msg.scores.fluency ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">🧩 完整度 (Completeness):</span>
                                            <span className="sc-score-value">{msg.scores.completeness ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-divider" />
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">📝 语法得分 (Grammar):</span>
                                            <span className="sc-score-value">{msg.scores.grammar ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">🎓 切题度 (Relevance):</span>
                                            <span className="sc-score-value">{msg.scores.relevance ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                        <div className="sc-score-item">
                                            <span className="sc-score-label">📚 词汇运用 (Vocabulary):</span>
                                            <span className="sc-score-value">{msg.scores.vocab ?? '--'} <span style={{ fontSize: '11px', color: '#9ca3af' }}>/ 100</span></span>
                                        </div>
                                    </div>
                                </details>
                            )}
                        </div>
                    ))}

                    {/* Live transcript bubble while listening */}
                    {status === 'listening' && liveTranscript && (
                        <div className="sc-bubble sc-bubble-user sc-bubble-live">
                            <span className="sc-live-dot" />
                            <span>{liveTranscript}</span>
                        </div>
                    )}

                    {/* Thinking bubble while AI processes */}
                    {status === 'processing' && (
                        <div className="sc-bubble sc-bubble-assistant sc-bubble-thinking">
                            <span className="sc-thinking-dot" />
                            <span className="sc-thinking-dot" />
                            <span className="sc-thinking-dot" />
                        </div>
                    )}

                    <div ref={messagesEndRef} />
                </div>

                {/* ── Controls ── */}
                <div className="sc-controls">
                    <div className="sc-status-bar">
                        {/* Status indicator */}
                        <div className={`sc-status-indicator sc-status-${status}`}>
                            <span className="sc-dot" />
                            <span>{STATUS_LABEL[status]}</span>
                            {status === 'listening' && (
                                <span className="sc-recording-time">{formatTime(recordingTime)}</span>
                            )}
                        </div>

                        {/* Waveform during recording */}
                        {status === 'listening' && (
                            <div className="sc-waveform">
                                {Array.from({ length: BAR_COUNT }).map((_, i) => {
                                    const h = Math.max(4, audioLevel * (Math.sin(i * 2.4) * 0.5 + 0.5));
                                    return <div key={i} className="sc-waveform-bar" style={{ height: `${h}%` }} />;
                                })}
                            </div>
                        )}

                        {/* Hint / error */}
                        <div className="sc-transcript-hint">
                            {recError
                                ? <span className="sc-rec-error">⚠️ {recError}</span>
                                : status === 'idle' ? '轮到你说话啦，按下绿色按钮开始'
                                    : status === 'mic_loading' ? '请在浏览器弹窗中允许麦克风权限...'
                                        : status === 'listening' ? '正在录音，说完后点击红色按钮停止'
                                            : status === 'processing' ? 'AI 正在生成回复，请稍候...'
                                                : status === 'speaking' ? '正在播放，播完后按钮变绿可继续'
                                                    : '正在加载，请稍候...'}
                        </div>
                    </div>

                    {/* Main mic button */}
                    <button
                        id="sc-mic-button"
                        className={`sc-mic-btn sc-mic-${status}`}
                        onClick={toggleRecording}
                        disabled={isDisabled}
                    >
                        {MIC_LABEL[status]}
                    </button>
                </div>
            </main>
        </div>
    );
}
